import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { listPuzzleIds, PUZZLE_DIR } from "./puzzles";

function identifier(id: string): string {
  return id.replace("-", "");
}

// Regenerates src/content/puzzles/index.ts so every puzzle file is part of the collection
export function writeIndex(): string[] {
  const ids = listPuzzleIds();
  const lines = [
    "// Generated by `pnpm puzzle:build`. Lists every puzzle file in this folder.",
    'import "server-only";',
    'import type { Puzzle } from "@/engine/puzzle";',
    ...ids.map((id) => `import ${identifier(id)} from "./${id}";`),
    "",
    `export const PUZZLES: readonly Puzzle[] = [${ids.map(identifier).join(", ")}];`,
    "",
  ];
  writeFileSync(join(PUZZLE_DIR, "index.ts"), lines.join("\n"));
  return ids;
}
